const course = "JS";          // outer scope
function show() {
  const lesson = "Closures";  // only visible inside show
  return course + ": " + lesson;
}
show();          // "JS: Closures"
// lesson;       // ReferenceError: lesson is not defined

function makeCounter() {
  let count = 0;              // private: nothing outside can touch it directly
  return () => {
    count += 1;
    return count;
  };
}

const a = makeCounter();
const b = makeCounter();
a(); // 1
a(); // 2
b(); // 1  (b has its own count)

function makeCounter() {
  let count = 0;
  return () => ++count;
}
const next = makeCounter();
next(); // 1
next(); // 2
